  function drillRows(){const rows=drill.set==='confirmed'?snapshot.confirmed:snapshot.cohort;return rows.filter(o=>{if(drill.kind==='hospital')return o.hospital===drill.key;if(drill.kind==='confirmedHospital')return o.hospital===drill.key&&o.completed;if(drill.kind==='product')return o.rows.some(r=>keyOf(r)===drill.key);if(drill.kind==='period')return periodKey(drill.set==='confirmed'?o.confirmedDate:o.received,snapshot.filters.period)===drill.key;return true;}).map(o=>{if(drill.kind!=='product')return o;return {...o,rows:o.rows.filter(r=>keyOf(r)===drill.key),results:o.results.filter(r=>keyOf(r)===drill.key)};}).sort((a,b)=>a.received.localeCompare(b.received)||a.id.localeCompare(b.id));}
